  ('81f16356-f1db-57ff-9ef0-33668674e5a1', null, (select id from public.skills where slug = 'read-g7-theme-summary'), null, 'easy',
   $q$Which statement best expresses a theme of the passage?$q$, $q$[{"text":"Practice is useless because accidents can happen anyway.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Coaches should never talk with athletes about their mistakes.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Relay races are always won by the team with the fastest runner.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"One mistake does not define a person; the way they respond matters more.","is_correct":true}]$q$::jsonb, $q$One mistake does not define a person; the way they respond matters more.$q$, $q$Jalen's coach shows him the strong race he ran after the drop, and he responds by practicing until his handoff is clean. The story shows practice paying off, so it does not suggest practice is useless.$q$, 'draft', 'c0a98cc7-05e4-5ea8-944a-280e23b2f42e')
