-- Passage rg7-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('eb35e28f-3ccf-550f-893c-d60177290a2e', 'rg7-theme-summary-p06', (select id from public.skills where slug = 'read-g7-theme-summary'), null,
        '6-8', $q$Grandfather's Radio$q$, $q$It sits on the shelf above the stove,
a wooden box with a cloth-covered face.
The dials are cracked. The paint is worn.
It is the oldest thing in the place.

He carried it across an ocean once,
wrapped in a sweater, packed with care.
At night he turned the dial for home.
He heard faint voices in the air.

When I was small, I asked to play
a game instead of hearing more.
He only nodded, turned it low,
and let me run out through the door.

Now I sit with him on Sunday nights.
He tells me which songs his mother knew.
He hums the parts the static hides.
I learn the words and hum them too.

The radio cannot catch those stations now.
The towers there went quiet long ago.
But every song he gives to me
travels farther than radios go.$q$, 'draft')
