  ('7eef9014-efc6-592a-a15b-7800fed229e3', null, (select id from public.skills where slug = 'read-g8-argument-evidence'), null, 'hard',
   $q$Which evidence, if added, would most strengthen the author's argument that the garden is worth the change?$q$, $q$[{"text":"A description of the color of the stone that would be used for the path.","is_correct":false,"misconception_token":"too-narrow"},{"text":"A list of the different grass types that grow well in the region.","is_correct":false,"misconception_token":"misjudges-relevance"},{"text":"A comparison of what the lawn and the garden would each cost to care for over five years.","is_correct":true},{"text":"A history of how the town was founded and who first settled there.","is_correct":false,"misconception_token":"misjudges-relevance"}]$q$::jsonb, $q$A comparison of what the lawn and the garden would each cost to care for over five years.$q$, $q$A cost comparison would add new, relevant evidence about whether the change is practical, which the passage never addresses with numbers. Grass types and town history do not help show that a garden is better than the lawn.$q$, 'draft', '8746a211-e31f-5ef9-b9c0-c8ab12fc9639')
