  ('71b45d85-6518-5f47-837d-fc3d7cc0344b', null, (select id from public.skills where slug = 'read-g8-argument-evidence'), null, 'medium',
   $q$Why was Moreau's reminder that Fenwick had lived in Millbrook for only five years irrelevant to the debate?$q$, $q$[{"text":"How long she had lived in town says nothing about whether electric lights were a good idea.","is_correct":true},{"text":"Five years is long enough to understand every problem a town has.","is_correct":false,"misconception_token":"misses-the-point"},{"text":"Fenwick had actually lived in Dalton during those five years.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The council had already voted before Moreau mentioned it.","is_correct":false,"misconception_token":"misreads-sequence"}]$q$::jsonb, $q$How long she had lived in town says nothing about whether electric lights were a good idea.$q$, $q$The reminder attacks the speaker instead of her evidence, and it does not change the accident records or the shop owners' promises. Whether five years is long or short does not matter, because the length of her stay has no bearing on the lights.$q$, 'draft', '1320f481-cf9c-5b60-9035-011cd5957c22')
