  ('a238bdee-9c38-51ec-b2e5-4a409b0eb430', null, (select id from public.skills where slug = 'read-g8-authors-purpose'), null, 'hard',
   $q$How does the final paragraph respond to the possibility that the mural could fail?$q$, $q$[{"text":"It argues that a failure would be easy to undo, while success would last.","is_correct":true},{"text":"It promises that the mural cannot fail because the teacher will help.","is_correct":false,"misconception_token":"overstates-claim"},{"text":"It admits that a failure would waste the grant and should stop the plan.","is_correct":false,"misconception_token":"misreads-concession"},{"text":"It claims that students would learn nothing if the mural turned out badly.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It argues that a failure would be easy to undo, while success would last.$q$, $q$The author says a failed mural "can be painted beige again in an afternoon" and concludes "The risk is small, and the reward is large." The author begins with "If the mural fails," so the author does not promise it cannot fail.$q$, 'draft', 'c15ebd96-1aae-53fe-acf0-d34296bc990a')
