  ('7add851a-12cc-5ecd-b795-ce075f0598c7', null, (select id from public.skills where slug = 'read-g8-authors-purpose'), null, 'easy',
   $q$What is the author's main purpose?$q$, $q$[{"text":"To explain how towns collect and haul away bags of leaves.","is_correct":false,"misconception_token":"too-narrow"},{"text":"To teach readers how to identify beetles and caterpillars.","is_correct":false,"misconception_token":"off-topic"},{"text":"To persuade homeowners to leave some fallen leaves in their yards.","is_correct":true},{"text":"To argue that neighborhood associations should be ended.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$To persuade homeowners to leave some fallen leaves in their yards.$q$, $q$The author writes "leave at least some of the leaves where they fall" and gives reasons for it. Leaf collection is mentioned only as a cost of bagging, not as the purpose.$q$, 'draft', 'b2b90ff1-915e-5d1d-9a20-f036f60d28c7')
