-- Passage rg8-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('52f196f4-28af-5cfa-a52d-80b5ff0c270d', 'rg8-character-setting-plot-p02', (select id from public.skills where slug = 'read-g8-character-setting-plot'), null,
        '6-8', $q$Third Leg$q$, $q$The gym was loud with sneakers and with names,
and Keiko held her breath at the third mark.
Her coach had said, "Just run your part. That's all."
She told herself those words a hundred times.

The baton came to her a little late.
Her teammate Rosa stumbled at the line
and called out, "Go! Don't wait for me. Just go!"
So Keiko went, and did not look behind.

She heard the crowd but could not hear her feet.
She passed one runner, then she passed one more.
She thought of Rosa's knee against the floor.
She thought, "My part is bigger now. I'll run it."

At the last mark, Dev reached back his hand.
She slapped the baton home and watched him fly.
They did not win. They finished in second place.
But when she turned, she saw that Rosa stood.

Rosa was limping, laughing, with her arms
held high as if the team had won the meet.
"You ran it," Rosa said. "You ran for both."
And Keiko, out of breath, could only nod.$q$, 'draft')
