  ('d95ff300-c046-543d-b113-e004f9d54ec2', null, (select id from public.skills where slug = 'read-g8-connections'), null, 'hard',
   $q$Which statement best describes how the author develops the connection between postcards and packets?$q$, $q$[{"text":"The author explains the internet first, then uses postcards to argue that mail is more reliable.","is_correct":false,"misconception_token":"wrong-purpose"},{"text":"The author compares the two systems to show that they are equally fast and equally reliable.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The author sets up a familiar comparison, applies it, then shows where it stops being accurate.","is_correct":true},{"text":"The author lists the steps of mailing to prove that the internet was copied from the post office.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The author sets up a familiar comparison, applies it, then shows where it stops being accurate.$q$, $q$Paragraph 2 builds the postcard example, paragraph 3 applies it to packets, and paragraph 4 explains its "limits." The author notes the internet recovers lost packets and is much faster, so the systems are not equal.$q$, 'draft', '0ae7cec1-58ad-59f3-9b55-0ac33ca83430')
