  ('a278a5d7-5837-5941-bfc0-66804ebdeecc', null, (select id from public.skills where slug = 'read-g8-context-clues'), null, 'easy',
   $q$In paragraph 1, keepers had to stay "vigilant" through the night. What does "vigilant" mean?$q$, $q$[{"text":"watchful and alert","is_correct":true},{"text":"lonely and quiet","is_correct":false,"misconception_token":"wrong-context-clue"},{"text":"brave and strong","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"asleep and resting","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$watchful and alert$q$, $q$Keepers "watched the flame" and "checked the weather" because "a single careless hour" was dangerous, so vigilant means watchful and alert. Loneliness is discussed later in the passage and does not explain this word.$q$, 'draft', 'dea1a239-7b14-599e-9914-0ddbc58f17f7')
