values
  ('fb91979b-bc75-508b-a84d-d3d33be544ea', null, (select id from public.skills where slug = 'read-g8-evidence-inference'), null, 'hard',
   $q$Which inference is best supported by BOTH the third paragraph and the final paragraph?$q$, $q$[{"text":"Only people under thirty were surprised to see the lighthouse.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The team added the lighthouse to give the mural a fresh idea.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The lighthouse had been gone so long that even people who saw it forgot it.","is_correct":true},{"text":"The lighthouse was the most popular part of the original mural.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The lighthouse had been gone so long that even people who saw it forgot it.$q$, $q$The third paragraph says it faded completely, and in the last paragraph an older man says he "had forgotten all about it." His surprise shows older people were affected too, so the choice about only younger people is wrong.$q$, 'draft', '907d3804-cc16-5957-b6c5-115b7eb8ad05')
