values
  ('4d715cf8-a4f8-5d48-9450-0e497e6a47b8', null, (select id from public.skills where slug = 'read-g8-evidence-inference'), null, 'easy',
   $q$What does the author say the school should do?$q$, $q$[{"text":"Build a new public library on the school's side of the highway.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Open the library at least two mornings a week in summer.","is_correct":true},{"text":"Close the library earlier in June to save money.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Keep the library open all day, every day, in summer.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$Open the library at least two mornings a week in summer.$q$, $q$The first paragraph states the claim directly: open the library "at least two mornings a week during the summer." The author never asks for all-day hours.$q$, 'draft', '2513d238-1109-5d0b-8818-c4d390d2e932')
